const query = (name, schema, required = false) => ({ name, in: 'query', required, schema });
const selectors = ['PackProof-Merchant-Id', 'PackProof-Delegation-Id'].map(name => ({ name, in: 'header', schema: text(), description: 'Exact current delegated selector when required by the service credential.' }));
